// vendor/make-three.mjs — builds vendor/three.min.js, the slice of three.js
// the home page uses, and nothing else.
//
// The page has no build step; this is the one generated file, kept in the
// repository. It is made from three's own published build, keeping only the
// classes the page's modules reach for (every `THREE.Something` in them), so
// a first visit downloads about a fifth less and from the site itself rather
// than a separate CDN.
//
// To rebuild, after changing which parts of three the page uses or its
// version (keep THREE_VERSION in step with the import map in index.html):
//
//   npm i --no-save three@0.170.0 esbuild@0.24.0
//   node vendor/make-three.mjs

import { readFileSync, writeFileSync } from "node:fs";
import { build } from "esbuild";

const THREE_VERSION = "0.170.0";
const SOURCES = ["stage.js", "paper.js", "flame.js", "room-props.js"];

const used = new Set();
for (const file of SOURCES) {
  for (const [, name] of readFileSync(file, "utf8").matchAll(/THREE\.([A-Za-z0-9_]+)/g)) used.add(name);
}
const names = [...used].sort();
const result = await build({
  stdin: { contents: `export { ${names.join(", ")} } from "three";`, resolveDir: process.cwd() },
  bundle: true, format: "esm", minify: true, write: false, legalComments: "none"
});
const banner = `// three.js r${THREE_VERSION.split(".")[1]} (MIT, threejs.org/license), cut down to what the home page uses: ${names.join(", ")}.\n// Generated by vendor/make-three.mjs — rebuild rather than edit.\n`;
writeFileSync("vendor/three.min.js", banner + result.outputFiles[0].text);
console.log(`vendor/three.min.js: ${names.length} exports, ${(result.outputFiles[0].text.length / 1024).toFixed(0)} KB`);
